junipermist:org/gatewaytemplate:Gatewayt.description:
This resource manages the Gateway Templates.

A Gateway template is used to define the static ip address and subnet mask of the hub device, along with the gateway. It also allows for the selection of options such as enabling source nat and overriding the public ip for the hub if needed. the endpoint selected in the gateway template ties the hub and spoke devices together and creates the auto-vpn tunnel.


## Example Usage

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as junipermist from "@pulumi/juniper-mist";

const gatewaytemplateOne = new junipermist.org.Gatewaytemplate("gatewaytemplate_one", {
    type: "spoke",
    name: "gatewaytemplate_one",
    orgId: terraformTest.id,
    portConfig: {
        "ge-0/0/3": {
            name: "FTTH",
            usage: "wan",
            aggregated: false,
            redundant: false,
            critical: false,
            wanType: "broadband",
            ipConfig: {
                type: "static",
                ip: "192.168.1.8",
                netmask: "/24",
                gateway: "192.168.1.1",
            },
            disableAutoneg: false,
            speed: "auto",
            duplex: "auto",
            wanSourceNat: {
                disabled: false,
            },
            vpnPaths: {
                "SSR_HUB_DC-MPLS.OrgOverlay": {
                    key: 0,
                    role: "spoke",
                    bfdProfile: "broadband",
                },
            },
        },
        "ge-0/0/5": {
            usage: "lan",
            critical: false,
            aggregated: true,
            aeDisableLacp: false,
            aeLacpForceUp: true,
            aeIdx: "0",
            redundant: false,
            networks: [
                "PRD-Core",
                "PRD-Mgmt",
                "PRD-Lab",
            ],
        },
    },
    ipConfigs: {
        "PRD-Core": {
            type: "static",
            ip: "10.3.100.9",
            netmask: "/24",
        },
        "PRD-Mgmt": {
            type: "static",
            ip: "10.3.172.1",
            netmask: "/24",
        },
        "PRD-Lab": {
            type: "static",
            ip: "10.3.171.1",
            netmask: "/24",
        },
    },
    servicePolicies: [{
        name: "Policy-14",
        tenants: ["PRD-Core"],
        services: ["any"],
        action: "allow",
        pathPreference: "HUB",
        idp: {
            enabled: true,
            profile: "critical",
            alertOnly: false,
        },
    }],
});
