    orgId: terraformTest.id,
    name: "mxtunnel_one",
    protocol: "udp",
    helloInterval: 60,
    helloRetries: 7,
    mtu: 0,
    vlanIds: [
        10,
        20,
        30,
    ],
    mxclusterIds: [mxclusterOne.id],
    autoPreemption: {
        enabled: true,
        dayOfWeek: "mon",
        timeOfDay: "02:00",
    },
    ipsec: {
