        splitTunnel: true,
        useMxedge: true,
        dnsServers: [
            "8.8.8.8",
            "8.8.4.4",
        ],
        dnsSuffixes: ["corp.example.com"],
        extraRoutes: [{
            dest: "10.0.0.0/8",
            nextHop: "192.168.1.1",
        }],
    },
});
